104: function drawStarPath(ctx, cx, cy, outer, inner, points = 5) {
105:   ctx.beginPath();
106:   for (let i = 0; i < points * 2; i++) {
107:     const angle = -Math.PI / 2 + (i / (points * 2)) * TAU;
108:     const radius = i % 2 === 0 ? outer : inner;
109:     const x = cx + Math.cos(angle) * radius;
110:     const y = cy + Math.sin(angle) * radius;
111:     if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
112:   }
113:   ctx.closePath();
114: }
