116: function makeStickerTexture(type, color) {
117:   const canvas = makeTextCanvas(512, 256, (ctx, w, h) => {
118:     ctx.clearRect(0, 0, w, h);
119:     ctx.fillStyle = color;
120:     ctx.strokeStyle = color;
121:     ctx.lineCap = 'round';
122:     ctx.lineJoin = 'round';
123:     ctx.textAlign = 'center';
124:     ctx.textBaseline = 'middle';
125: 
126:     switch (type) {
127:       case 'number':
128:         ctx.font = '700 190px Rajdhani, sans-serif';
129:         ctx.fillText('07', w / 2, h / 2 + 8);
130:         break;
131:       case 'apex': {
132:         ctx.font = '700 112px Rajdhani, sans-serif';
133:         ctx.fillText('APEX', w / 2, h / 2 - 18);
134:         ctx.font = '600 38px Rajdhani, sans-serif';
135:         ctx.globalAlpha = 0.8;
136:         ctx.fillText('I N K', w / 2, h / 2 + 64);
137:         ctx.globalAlpha = 1;
138:         break;
139:       }
140:       case 'stripe':
141:         ctx.save();
142:         ctx.translate(w / 2, h / 2);
143:         ctx.rotate(-0.3);
144:         for (let i = -1; i <= 1; i++) ctx.fillRect(-178, i * 42 - 9, 356, 18);
145:         ctx.restore();
146:         break;
147:       case 'bolt': {
148:         ctx.beginPath();
149:         ctx.moveTo(285, 26);
150:         ctx.lineTo(138, 144);
151:         ctx.lineTo(242, 144);
152:         ctx.lineTo(205, 230);
153:         ctx.lineTo(374, 100);
154:         ctx.lineTo(264, 100);
155:         ctx.closePath();
156:         ctx.fill();
157:         break;
158:       }
159:       case 'star':
160:         drawStarPath(ctx, w / 2, h / 2, 104, 45, 5);
161:         ctx.fill();
162:         break;
163:       case 'checker': {
164:         const size = 34;
165:         const cols = 6;
166:         const rows = 3;
167:         const ox = w / 2 - (cols * size) / 2;
168:         const oy = h / 2 - (rows * size) / 2;
169:         for (let y = 0; y < rows; y++) {
170:           for (let x = 0; x < cols; x++) {
171:             if ((x + y) % 2 === 0) ctx.fillRect(ox + x * size, oy + y * size, size - 3, size - 3);
172:           }
173:         }
174:         break;
175:       }
176:       case 'flame': {
177:         ctx.beginPath();
178:         ctx.moveTo(256, 28);
179:         ctx.bezierCurveTo(350, 92, 352, 154, 306, 198);
180:         ctx.bezierCurveTo(326, 150, 286, 132, 268, 174);
181:         ctx.bezierCurveTo(252, 136, 210, 150, 218, 196);
182:         ctx.bezierCurveTo(166, 152, 184, 90, 256, 28);
183:         ctx.closePath();
184:         ctx.fill();
185:         ctx.globalCompositeOperation = 'destination-out';
186:         ctx.beginPath();
187:         ctx.moveTo(258, 132);
188:         ctx.bezierCurveTo(292, 158, 288, 188, 258, 206);
189:         ctx.bezierCurveTo(232, 180, 232, 156, 258, 132);
190:         ctx.closePath();
191:         ctx.fill();
192:         ctx.globalCompositeOperation = 'source-over';
193:         break;
194:       }
195:       default:
196:         break;
197:     }
198:   });
199:   return canvasTexture(canvas);
200: }
