213: function makeWheel(front, accentMat) {
214:   const radius = front ? 0.355 : 0.395;
215:   const width = front ? 0.34 : 0.46;
216:   const steer = new THREE.Group();
217:   const spin = new THREE.Group();
218:   steer.add(spin);
219: 
220:   const rubber = new THREE.MeshStandardMaterial({ color: 0x0c0d0f, roughness: 0.92, metalness: 0.05 });
221:   const rimMat = new THREE.MeshStandardMaterial({ color: 0x2c2f34, roughness: 0.35, metalness: 0.9 });
222: 
223:   const tireGeo = new THREE.CylinderGeometry(radius, radius, width, 28, 1);
224:   tireGeo.rotateZ(Math.PI / 2);
225:   const tire = new THREE.Mesh(tireGeo, rubber);
226:   tire.castShadow = true;
227:   spin.add(tire);
228: 
229:   // sidewall rings
230:   for (const side of [-1, 1]) {
231:     const ring = new THREE.Mesh(new THREE.TorusGeometry(radius * 0.79, 0.012, 6, 32), accentMat);
232:     ring.rotation.y = Math.PI / 2;
233:     ring.position.x = side * (width / 2 + 0.004);
234:     spin.add(ring);
235:   }
236: 
237:   // rim + spokes
238:   const rimGeo = new THREE.CylinderGeometry(radius * 0.6, radius * 0.6, width + 0.01, 24, 1);
239:   rimGeo.rotateZ(Math.PI / 2);
240:   const rim = new THREE.Mesh(rimGeo, rimMat);
241:   spin.add(rim);
242: 
243:   for (let k = 0; k < 5; k++) {
244:     const spoke = new THREE.Mesh(new THREE.BoxGeometry(width * 0.5, 0.045, radius * 1.24), rimMat);
245:     spoke.rotation.x = (k / 5) * Math.PI;
246:     spin.add(spoke);
247:   }
248:   const hub = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.075, width + 0.08, 12), accentMat);
249:   hub.geometry.rotateZ(Math.PI / 2);
250:   spin.add(hub);
251: 
252:   return { steer, spin, radius, width };
253: }
