1321: // Keep a short timeline of every car's race progress. Comparing the leader's
1322: // timeline against a chaser's current progress gives the time gap you would
1323: // see on an F1 timing tower, rather than a guessed distance/speed division.
1324: function recordGapHistory() {
1325:   if (!race || race.state !== 'racing') return;
1326:   const now = race.time;
1327:   const push = (history, progress) => {
1328:     const last = history[history.length - 1];
1329:     if (last && now - last.t < 90) return;
1330:     history.push({ t: now, p: progress });
1331:     if (history.length > 2600) history.splice(0, 400);
1332:   };
1333:   push(race.player.history, playerProgress());
1334:   for (const a of race.ai) {
1335:     const progress = a.finished ? race.totalLaps : Math.min(race.totalLaps, a.dist / race.track.length);
1336:     push(a.history, progress);
1337:   }
1338: }
