1340: function gapToLeaderSeconds(leader, progress, speed) {
1341:   const history = leader.history;
1342:   if (!history || history.length < 2) return 0;
1343:   const first = history[0];
1344:   const last = history[history.length - 1];
1345:   if (progress >= last.p) return 0;
1346:   if (progress < first.p) {
1347:     // Before the leader's first sample (the grid): no elapsed race time yet.
1348:     if (race.time < 600) return 0;
1349:     const metres = (first.p - progress) * race.track.length;
1350:     return metres / Math.max(24, speed);
1351:   }
1352:   // Binary search for the first timeline sample at or beyond this progress.
1353:   let lo = 0, hi = history.length - 1;
1354:   while (lo < hi) {
1355:     const mid = (lo + hi) >> 1;
1356:     if (history[mid].p >= progress) hi = mid; else lo = mid + 1;
1357:   }
1358:   const b = history[lo];
1359:   const a = history[Math.max(0, lo - 1)];
1360:   if (b === a) return Math.max(0, (race.time - b.t) / 1000);
1361:   const f = clamp((progress - a.p) / Math.max(1e-6, b.p - a.p), 0, 1);
1362:   const tAt = a.t + (b.t - a.t) * f;
1363:   return Math.max(0, (race.time - tAt) / 1000);
1364: }
