1441:   // Scan the road ahead and find the fastest speed we can still brake down to
1442:   // every upcoming corner from. This does the "when do I lift?" thinking.
1443:   for (let d = 0; d <= maxSteps; d += stride) {
1444:     const s = track.samples[(base + d) % N];
1445:     const radius = Math.max(1 / Math.max(Math.abs(s.k), 1e-5), 24);
1446:     const corner = Math.sqrt(AUTODRIVE.lateral * radius);
1447:     const dist = d * track.step;
