1559:   if (p.throttle < 0.02 && p.brake < 0.02 && !handbrake && Math.abs(vLong) < 0.2) vLong = 0;
1560: 
1561:   const sideGrip = p.offroad
1562:     ? HANDLING.sideGripOffroad
1563:     : handbrake
1564:       ? HANDLING.sideGripHandbrake
1565:       : p.onKerb
1566:         ? HANDLING.sideGripKerb
1567:         : HANDLING.sideGripTrack;
1568:   vLat *= Math.exp(-sideGrip * dt);
1569: 
1570:   p.vLong = vLong;
1571:   p.vLat = vLat;
1572:   p.vel.x = fx * vLong + rx * vLat;
1573:   p.vel.z = fz * vLong + rz * vLat;
1574:   p.pos.x += p.vel.x * dt;
1575:   p.pos.z += p.vel.z * dt;
1576: 
1577:   const near = nearestTrackSample(tr, p.pos.x, p.pos.z, p.lastIndex);
1578:   const sample = tr.samples[near.index];
1579:   p.lastIndex = near.index;
1580:   p.sNorm = (near.index % tr.N) / tr.N;
1581:   p.trackDist = near.dist;
1582:   p.lastK = sample.k;
1583:   p.offroad = near.dist > tr.halfWidth + 1.15;
1584:   p.onKerb = !p.offroad && near.dist > tr.halfWidth - 0.55 && near.dist < tr.halfWidth + 1.6;
1585:   if (p.offroad) {
1586:     p.offTimer += dt * (near.dist > tr.halfWidth + 25 ? 2 : 1);
1587:   } else {
1588:     p.offTimer = Math.max(0, p.offTimer - dt * 2.5);
1589:   }
1590:   if (race.state === 'racing' && p.offTimer > 2.7) recoverPlayer();
1591: 
1592:   const kmh = Math.abs(vLong) * 3.6;
1593:   if (race.state === 'racing') p.topSpeed = Math.max(p.topSpeed, kmh);
1594: }
