1596: function updatePlayerVisual(dt) {
1597:   const p = race.player;
1598:   const car = race.playerCar;
1599:   car.root.position.set(p.pos.x, 0, p.pos.z);
1600:   car.root.rotation.y = p.yaw;
1601: 
1602:   const longAccel = (p.vLong - p.prevVLong) / Math.max(dt, 0.001);
1603:   p.prevVLong = p.vLong;
1604:   car.body.rotation.x = damp(car.body.rotation.x, clamp(-longAccel * 0.0022, -0.055, 0.055), 7, dt);
1605:   car.body.rotation.z = damp(car.body.rotation.z, clamp(p.vLong * p.yawRate * 0.0032, -0.07, 0.07), 7, dt);
1606: 
1607:   const steerVisual = p.steer * lerp(
1608:     HANDLING.steerLowSpeed * 0.82,
1609:     HANDLING.steerHighSpeed * 1.2,
1610:     clamp(Math.abs(p.vLong) / HANDLING.steerSpeedRef, 0, 1)
1611:   );
