1613:     w.spin.rotation.x += (p.vLong / w.radius) * dt;
1614:     if (w.front) w.steer.rotation.y = damp(w.steer.rotation.y, steerVisual, 18, dt);
1615:   }
1616:   car.setBrake(p.brake > 0.08 || race.state === 'finished');
1617:   car.setDRS(p.drs);
