1619:   // tyre smoke and grass dust
1620:   const slip = Math.abs(p.vLat);
1621:   const speed = Math.abs(p.vLong);
1622:   const rate = p.offroad && speed > 4 ? 42 : (slip > 2.4 && speed > 6 ? 26 : 0);
1623:   if (rate && race.state !== 'countdown') {
1624:     emitAccum += dt * rate;
1625:     while (emitAccum >= 1) {
1626:       emitAccum -= 1;
1627:       const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
1628:       const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
1629:       const side = Math.random() > 0.5 ? 1 : -1;
1630:       const x = p.pos.x - fx * 1.65 + rx * side * 0.85;
1631:       const z = p.pos.z - fz * 1.65 + rz * side * 0.85;
1632:       const color = p.offroad ? DUST_COLOR : SMOKE_COLOR;
1633:       race.smoke.emit(x, 0.22, z, color, p.offroad ? 0.9 : 0.7, p.offroad ? 1.25 : 1.0, p.offroad ? 2.4 : 1.6);
1634:     }
1635:   }
