1638: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1639:   const N = track.N;
1640:   let best = -1;
1641:   let bestD = Infinity;
1642:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1643:     const span = Math.max(6, Math.round(windowMeters / track.step));
1644:     for (let k = -span; k <= span; k++) {
1645:       const i = (hint + k + N) % N;
1646:       const s = track.samples[i];
1647:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1648:       if (d < bestD) { bestD = d; best = i; }
1649:     }
1650:     // If the car is well off the road (or has been recovered), fall back to the
1651:     // spatial lookup so it can always find its way back to the nearest asphalt.
1652:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1653:       const global = race.locator.nearest(x, z);
1654:       const d = global.dist * global.dist;
1655:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1656:     }
1657:   }
1658:   if (best < 0) {
1659:     const global = race.locator.nearest(x, z);
1660:     best = global.index >= 0 ? global.index : 0;
1661:     bestD = global.dist * global.dist;
1662:   }
1663:   return { index: best, dist: Math.sqrt(bestD) };
1664: }
1665: 
1666: function trackDistanceAt(track, index, x, z) {
1667:   const s = track.samples[index];
1668:   const along = (x - s.x) * s.tx + (z - s.z) * s.tz;
1669:   return (s.s ?? index * track.step) + clamp(along, -track.step, track.step);
1670: }
1671: 
1672: function unwrapTrackDistance(candidate, reference, length) {
1673:   let out = candidate;
1674:   const half = length * 0.5;
1675:   while (out - reference > half) out -= length;
1676:   while (out - reference < -half) out += length;
1677:   return out;
1678: }
1679: 
1680: function recoverPlayer(showToast = true) {
1681:   const p = race.player;
1682:   const near = nearestTrackSample(race.track, p.pos.x, p.pos.z, p.lastIndex);
1683:   const s = race.track.samples[near.index];
1684:   p.pos = { x: s.x, z: s.z };
1685:   p.vel = { x: 0, z: 0 };
1686:   p.vLong = 0; p.vLat = 0;
1687:   p.yaw = Math.atan2(s.tx, s.tz);
1688:   p.offroad = false;
1689:   p.offTimer = 0;
1690:   p.lastIndex = near.index;
1691:   p.sNorm = (near.index % race.track.N) / race.track.N;
1692:   p.progressDist = unwrapTrackDistance(trackDistanceAt(race.track, near.index, s.x, s.z), p.progressDist, race.track.length);
1693:   race.locator.lastIndex = near.index;
1694:   // Cut the camera with the car rather than letting it swoop across the
1695:   // circuit to the recovery point.
1696:   race.camYaw = p.yaw;
1697:   race.cameraReady = false;
1698:   race.camLook.set(s.x + Math.sin(p.yaw) * 7, 0.92, s.z + Math.cos(p.yaw) * 7);
1699:   race.smoke.reset();
1700:   if (showToast) {
1701:     toast('Recovered to the racing line');
1702:     audio.tone(330, 0.1, 0.04, 'triangle');
1703:   }
1704: }
