1706: /* ═══════════════════════════════════════════════════════════════════
1707:    Lap logic
1708:    ═══════════════════════════════════════════════════════════════════ */
1709: function completeLap() {
1710:   const p = race.player;
1711:   const lapTime = race.time - p.lapStart;
1712:   if (lapTime > 3000) {
1713:     p.lastLap = lapTime;
1714:     if (!p.bestLap || lapTime < p.bestLap) {
1715:       p.bestLap = lapTime;
1716:       writeBest(race.track.seed, lapTime);
1717:       toast(`NEW BEST LAP · ${formatTime(lapTime)}`);
1718:     }
1719:   }
1720:   p.lapsCompleted++;
1721:   p.lapStart = race.time;
1722:   p.sectors = [false, false, false];
1723:   if (p.lapsCompleted >= race.totalLaps) {
1724:     finishRace();
1725:   } else if (p.lapsCompleted === race.totalLaps - 1) {
1726:     showRaceMessage('FINAL LAP', 'EVERYTHING YOU HAVE', 2300, true);
1727:     audio.tone(880, 0.18, 0.06, 'triangle');
1728:   } else {
1729:     showRaceMessage(`LAP ${p.lapsCompleted + 1} / ${race.totalLaps}`, 'KEEP IT CLEAN', 1900);
1730:     audio.tone(660, 0.1, 0.04, 'triangle');
1731:   }
1732: }
