1734: function updatePlayerProgress(dt) {
1735:   const p = race.player;
1736:   if (p.finished) return;
1737:   const tr = race.track;
1738:   const L = tr.length;
1739:   const near = nearestTrackSample(tr, p.pos.x, p.pos.z, p.lastIndex);
1740:   const candidate = unwrapTrackDistance(
1741:     trackDistanceAt(tr, near.index, p.pos.x, p.pos.z),
1742:     p.progressDist,
1743:     L
1744:   );
1745: 
1746:   // A car can only advance a sensible distance in one physics step. Clamping
1747:   // rejected huge jumps from nearby track sections while still letting the
1748:   // progress catch up after a recovery.
1749:   const allowed = Math.max(16, Math.abs(p.vLong) * Math.max(dt, 0.001) * 4 + 3);
1750:   const delta = candidate - p.progressDist;
1751:   p.progressDist += Math.abs(delta) <= allowed ? delta : clamp(delta, -allowed, allowed);
1752:   p.lastIndex = near.index;
1753:   p.trackDist = near.dist;
1754:   p.sNorm = (((p.progressDist % L) + L) % L) / L;
1755: 
1756:   // Hidden checkpoints. The lap only counts after every gate has been crossed
1757:   // in order, which keeps the timing tower honest even on circuits that fold
1758:   // back alongside themselves.
1759:   const cpCount = race.checkpoints.length;
1760:   const cpSpacing = L / cpCount;
1761:   if (p.cpArmed) {
1762:     if (p.progressDist >= (p.lapsCompleted + 1) * L) {
1763:       p.cpArmed = false;
1764:       p.cpNext = 1;
1765:       completeLap();
1766:     }
1767:   } else {
1768:     const target = p.lapsCompleted * L + p.cpNext * cpSpacing;
1769:     if (p.progressDist >= target) {
1770:       if (p.cpNext >= cpCount - 1) {
1771:         p.cpArmed = true;
1772:         p.cpNext = 0;
1773:       } else {
1774:         p.cpNext++;
1775:       }
1776:     }
1777:   }
1778: 
1779:   const lapFrac = (((p.progressDist % L) + L) % L) / L;
1780:   if (lapFrac > 0.13) p.sectors[0] = true;
1781:   if (lapFrac > 0.38) p.sectors[1] = true;
1782:   if (lapFrac > 0.64) p.sectors[2] = true;
1783: }
