1785: /* ═══════════════════════════════════════════════════════════════════
1786:    AI drivers
1787:    ═══════════════════════════════════════════════════════════════════ */
1788: /* Cars are three overlapping circles rather than one big invisible circle, so
1789:    contact happens where the bodywork actually is. When you run into another
1790:    car you scrub speed and get nudged along it — the closing speed is killed,
1791:    never reflected, so you are not fired backwards like a rubber ball. */
1792: const CONTACT = {
1793:   offsets: [1.45, 0, -1.45],
1794:   radii: [1.02, 1.06, 1.02]
1795: };
1796: const SPARK_COLOR = new THREE.Color(0xffb257);
1797: const playerCircles = new Float32Array(6);
1798: const aiCircles = new Float32Array(6);
1799: let contactCooldown = 0;
1800: 
1801: function fillCarCircles(x, z, yaw, out) {
1802:   const fx = Math.sin(yaw);
1803:   const fz = Math.cos(yaw);
1804:   for (let i = 0; i < 3; i++) {
1805:     const o = CONTACT.offsets[i];
1806:     out[i * 2] = x + fx * o;
1807:     out[i * 2 + 1] = z + fz * o;
1808:   }
1809:   return out;
1810: }
1811: 
1812: function resolveCarCollisions(dt = 1 / 60) {
1813:   const p = race.player;
1814:   const tr = race.track;
1815:   if (contactCooldown > 0) contactCooldown = Math.max(0, contactCooldown - dt);
1816: 
1817:   fillCarCircles(p.pos.x, p.pos.z, p.yaw, playerCircles);
1818: 
1819:   for (const a of race.ai) {
1820:     const ax = a.model.root.position.x;
1821:     const az = a.model.root.position.z;
1822:     const ayaw = a.model.root.rotation.y;
1823:     fillCarCircles(ax, az, ayaw, aiCircles);
1824: 
1825:     let overlap = 0;
1826:     let nx = 0;
1827:     let nz = 0;
1828:     let contactX = 0;
1829:     let contactZ = 0;
1830:     for (let i = 0; i < 3; i++) {
1831:       const px = playerCircles[i * 2];
1832:       const pz = playerCircles[i * 2 + 1];
1833:       for (let j = 0; j < 3; j++) {
1834:         const cx = aiCircles[j * 2];
1835:         const cz = aiCircles[j * 2 + 1];
1836:         const dx = px - cx;
1837:         const dz = pz - cz;
1838:         const dist = Math.hypot(dx, dz) || 0.0001;
1839:         const deep = CONTACT.radii[i] + CONTACT.radii[j] - dist;
1840:         if (deep <= overlap) continue;
1841:         overlap = deep;
1842:         nx = dx / dist;
1843:         nz = dz / dist;
1844:         contactX = (px + cx) * 0.5;
1845:         contactZ = (pz + cz) * 0.5;
1846:       }
1847:     }
1848:     if (overlap <= 0) continue;
1849: 
1850:     const aFx = Math.sin(ayaw);
1851:     const aFz = Math.cos(ayaw);
1852:     const aRx = Math.cos(ayaw);
1853:     const aRz = -Math.sin(ayaw);
1854:     const aiVx = aFx * a.speed;
1855:     const aiVz = aFz * a.speed;
1856:     const relVx = p.vel.x - aiVx;
1857:     const relVz = p.vel.z - aiVz;
1858:     const vn = relVx * nx + relVz * nz;
1859: 
1860:     // Split the positional separation between the two cars. The player is
1861:     // shoved sideways off the other car; the AI takes the rest as a shove
1862:     // along the track, so you can lean on it and muscle past instead of
1863:     // bouncing back down the road.
1864:     const push = Math.min(overlap, 0.7);
1865:     p.pos.x += nx * push * 0.55;
1866:     p.pos.z += nz * push * 0.55;
1867: 
1868:     const s = sampleAtDistance(tr, a.dist);
1869:     const shove = push * 0.5;
1870:     a.dist += (s.tx * -nx + s.tz * -nz) * shove;
1871:     const latLimit = Math.max(2.4, tr.halfWidth - 1.6);
1872:     a.lateral = clamp(a.lateral + (s.nx * -nx + s.nz * -nz) * shove, -latLimit, latLimit);
1873: 
1874:     // Contact is always worth a small scrub and a side-step, even when the
1875:     // relative speed is tiny, so cars rub instead of sticking together.
1876:     const fx = Math.sin(p.yaw);
1877:     const fz = Math.cos(p.yaw);
1878:     const rx = Math.cos(p.yaw);
1879:     const rz = -Math.sin(p.yaw);
1880:     let impact = 0;
1881:     if (vn < 0) {
1882:       impact = Math.min(1, Math.abs(vn) / 26);
1883:       // Remove only the speed heading into the other car. Whatever speed you
1884:       // carry along the contact patch stays, so you keep driving forward.
1885:       p.vel.x -= nx * vn;
1886:       p.vel.z -= nz * vn;
1887:       const tanVx = relVx - nx * vn;
1888:       const tanVz = relVz - nz * vn;
1889:       const scrub = 0.07 + impact * 0.16;
1890:       p.vel.x -= tanVx * scrub;
1891:       p.vel.z -= tanVz * scrub;
1892: 
1893:       // How square-on the hit is: 1 = straight up the gearbox, 0 = pure
1894:       // side swipe. Square-on hits get a firm side-step so you peel around
1895:       // the car ahead instead of grinding along behind it.
1896:       const squareOn = Math.abs(nx * fx + nz * fz);
1897:       const sideOff = (p.pos.x - ax) * aRx + (p.pos.z - az) * aRz;
1898:       const side = Math.abs(sideOff) > 0.12 ? Math.sign(sideOff) : (p.vLat >= 0 ? 1 : -1);
1899:       const escape = (0.5 + impact * 3.2) * (0.35 + squareOn * 0.65);
1900:       p.vel.x += aRx * side * escape;
1901:       p.vel.z += aRz * side * escape;
1902: 
1903:       // A shove up the road for the car ahead, so it does not feel like a wall.
1904:       a.speed += impact * 1.8;
1905:     }
1906: 
1907:     p.vLong = p.vel.x * fx + p.vel.z * fz;
1908:     p.vLat = p.vel.x * rx + p.vel.z * rz;
1909:     // The shove changed where the player is; refresh its circles before the
1910:     // next car is tested so a three-wide squeeze resolves in one frame.
1911:     fillCarCircles(p.pos.x, p.pos.z, p.yaw, playerCircles);
1912: 
1913:     // Keep the AI model where we just shoved it so the next frame agrees.
1914:     const as = sampleAtDistance(tr, a.dist);
1915:     const lat = a.lateral + Math.sin(a.dist / 44 + a.phase) * 0.85;
1916:     const ax2 = as.x + as.nx * lat;
1917:     const az2 = as.z + as.nz * lat;
1918:     a.model.root.position.set(ax2, 0, az2);
1919:     a.model.root.rotation.y = Math.atan2(as.tx, as.tz);
1920: 
1921:     if (vn < -1.4 && contactCooldown <= 0) {
1922:       contactCooldown = 0.22;
1923:       const power = clamp(Math.abs(vn) / 24, 0.15, 1);
1924:       for (let k = 0; k < 7; k++) {
1925:         race.smoke.emit(contactX, 0.45 + Math.random() * 0.5, contactZ, SPARK_COLOR,
1926:           0.2 + Math.random() * 0.18, 0.24 + Math.random() * 0.2, 3.4);
1927:       }
1928:       race.impactShake = Math.max(race.impactShake || 0, 0.25 + power * 0.45);
1929:       audio.impact(power);
1930:     }
1931:   }
1932: }
