1934: function findAiBlocker(a, ai) {
1935:   let blocker = null;
1936:   let gap = Infinity;
1937:   for (const b of ai) {
1938:     if (b === a || b.lane !== a.lane) continue;
1939:     const d = b.dist - a.dist;
1940:     if (d > 0.2 && d < gap && d < 45) { blocker = b; gap = d; }
1941:   }
1942:   return { blocker, gap };
1943: }
1944: 
1945: function aiLaneClear(a, lane, ai) {
1946:   for (const b of ai) {
1947:     if (b === a || b.lane !== lane) continue;
1948:     const d = b.dist - a.dist;
1949:     if (d > -8 && d < 15) return false;
1950:   }
1951:   return true;
1952: }
1953: 
1954: function updateAI(dt) {
1955:   const tr = race.track;
1956:   const L = tr.length;
1957:   const diff = DIFFICULTY[diffLevel] || DIFFICULTY.pro;
1958:   const ai = race.ai;
1959: 
1960:   // Decide who is stuck behind whom before anyone moves.
1961:   for (const a of ai) {
1962:     a.laneCooldown = Math.max(0, a.laneCooldown - dt);
1963:     a.formTimer -= dt;
1964:     if (a.formTimer <= 0) {
1965:       a.formTimer = 7 + Math.random() * 8;
1966:       a.formTarget = 0.985 + Math.random() * 0.03;
1967:     }
1968:     a.form = damp(a.form, a.formTarget, 0.55, dt);
1969:     const look = findAiBlocker(a, ai);
1970:     a.blocker = look.blocker;
1971:     a.blockerGap = look.gap;
1972:   }
1973: 
1974:   // Faster cars look for a clear lane and go racing. The quickest drivers are
1975:   // prepared to commit from further back; the conservative ones wait a little.
1976:   for (const a of ai) {
1977:     const blocker = a.blocker;
1978:     if (!blocker || a.finished || a.laneCooldown > 0) continue;
1979:     const trigger = 11 + (a.nerve - 0.72) * 30;
1980:     if (a.blockerGap > trigger) continue;
1981:     const quicker = a.pace * a.form > blocker.pace * blocker.form * 0.999;
1982:     const aboutToHit = a.blockerGap < 6.5;
1983:     if (!quicker && !aboutToHit) continue;
1984:     const dirs = a.lane === 0 ? [1] : a.lane === AI_LANES.length - 1 ? [-1]
1985:       : (Math.random() < 0.5 ? [-1, 1] : [1, -1]);
1986:     for (const dir of dirs) {
1987:       const lane = a.lane + dir;
1988:       if (lane < 0 || lane >= AI_LANES.length) continue;
1989:       if (!aiLaneClear(a, lane, ai)) continue;
1990:       a.lane = lane;
1991:       a.laneCooldown = 1.2 + Math.random() * 1.4;
1992:       break;
1993:     }
1994:   }
1995: 
1996:   for (const a of ai) {
1997:     const norm = ((a.dist % L) + L) % L;
1998:     const idx = Math.floor(norm / tr.step) % tr.N;
1999:     const s = tr.samples[idx];
2000:     let target = tr.speedProfile[idx] * diff.factor * a.pace * a.form;
2001:     if (race.time < a.startDelay * 1000) target *= 0.35;
2002:     if (a.finished) target *= 0.55;
2003: 
2004:     // Traffic awareness: hold a gap to the car directly ahead in this lane,
2005:     // and only squeeze past once a neighbouring lane is clear.
2006:     if (a.blocker && a.blocker.lane === a.lane && !a.finished) {
2007:       const gap = a.blocker.dist - a.dist;
2008:       const room = 6.5 + a.speed * 0.03;
2009:       if (gap > 0 && gap < room) {
2010:         // Sit just behind the car ahead instead of bumping it, while the lane
2011:         // logic looks for a way past.
2012:         target = Math.min(target, Math.max(8, a.blocker.speed * (0.975 + (gap / room) * 0.02)));
2013:       } else if (gap >= room && gap < room + 14) {
2014:         target = Math.min(target, a.blocker.speed + (gap - room) * 0.35);
2015:       }
2016:     }
2017: 
2018:     // Small per-driver corner appetite: braver drivers carry a touch more pace
