import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

process.env.DISPLAY = ':0';
const browser = await chromium.launch({
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });

await page.goto('http://localhost:3000/?demo=race&go=1&track=0', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });

const result = await page.evaluate(async () => {
  const A = window.__apex;
  const r = A.race;
  r.world.update = () => {}; // skip visual world updates for a fast, deterministic sim
  const snapshots = [];
  const startOrder = r.ai.map((a) => ({ name: a.name, dist: a.dist, pace: a.pace, lateral: a.lateral }));
  const maxLaps = r.totalLaps;
  const L = r.track.length;
  const totalTicks = Math.ceil((maxLaps * 130) / 0.05);
  let lastLapOf = new Map();
  const overtakes = [];
  let prevOrder = [...r.ai].sort((a, b) => b.dist - a.dist).map((a) => a.name);
  for (let i = 0; i < totalTicks; i++) {
    A.tick(0.05);
    // Ignore player physics interference: park the player far off track? keep as is.
    if (i % 20 === 0) {
      const order = [...r.ai].sort((a, b) => b.dist - a.dist).map((a) => a.name);
      for (let k = 0; k < order.length; k++) {
        if (order[k] !== prevOrder[k]) {
          overtakes.push({ t: (r.time / 1000).toFixed(1), a: order[k], b: prevOrder[k] });
        }
      }
      prevOrder = order;
      snapshots.push({
        t: +(r.time / 1000).toFixed(1),
        order: order.join(','),
        gaps: r.ai.map((a) => +((a.dist - Math.max(...r.ai.map((x) => x.dist))) / 1).toFixed(0)),
        speeds: r.ai.map((a) => Math.round(a.speed * 3.6)),
        lats: r.ai.map((a) => +a.lateral.toFixed(1)),
        finished: r.ai.map((a) => a.finished)
      });
    }
    if (r.state === 'finished' || r.resultsShown) break;
  }
  return {
    startOrder,
    totalLaps: maxLaps,
    lapLength: L,
    timeSec: r.time / 1000,
    overtakes,
    final: r.ai.map((a) => ({ name: a.name, dist: +(a.dist / L).toFixed(3), finished: a.finished, finishTime: a.finishTime, pace: +a.pace.toFixed(3), lateral: +a.lateral.toFixed(2) })),
    snapshots: snapshots.filter((s, i) => i % 4 === 0),
    state: r.state,
    results: A.race ? null : null
  };
});

console.log(JSON.stringify(result, null, 2));
console.log('ERRORS:', errors);
await browser.close();

