import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

process.env.DISPLAY = ':0';
const browser = await chromium.launch({
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface']
});

const aiCount = Number(process.argv[2] || 3);
const raceCount = Number(process.argv[3] || 1);
const out = [];

for (let raceNo = 0; raceNo < raceCount; raceNo++) {
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
  await page.addInitScript((n) => {
    localStorage.setItem('apexink.ai', String(n));
    localStorage.setItem('apexink.laps', '3');
  }, aiCount);
  await page.goto('http://localhost:3000/?demo=race&go=1&track=0', { waitUntil: 'load' });
  await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });

  const result = await page.evaluate(async () => {
    const A = window.__apex;
    const r = A.race;
    r.world.update = () => {};
    r.player.finished = true; // keep the player out of the AI test

    const L = r.track.length;
    const grid = r.ai.map((a) => ({ name: a.name, dist: a.dist, pace: a.pace, finishTime: null }));
    const gridOrder = [...r.ai].sort((a, b) => b.dist - a.dist).map((a) => a.name);
    let leaderChanges = 0;
    let sideBySideFrames = 0;
    let totalFrames = 0;
    let minGapSum = 0;
    let minGapSamples = 0;
    let maxLateralPair = 0;
    let prevLeader = gridOrder[0];
    let prevOrder = gridOrder.slice();
    const swaps = [];

    const totalTicks = Math.ceil(260 / 0.05);
    for (let i = 0; i < totalTicks; i++) {
      A.tick(0.05);
      totalFrames++;
      const order = [...r.ai].sort((a, b) => b.dist - a.dist);
      if (order[0].name !== prevLeader) {
        leaderChanges++;
        prevLeader = order[0].name;
      }
      const names = order.map((a) => a.name);
      for (let k = 0; k < names.length; k++) {
        if (names[k] !== prevOrder[k]) {
          swaps.push({ t: +(r.time / 1000).toFixed(1), gained: names[k], lost: prevOrder[k] });
        }
      }
      prevOrder = names;
      // measure how close the field runs
      let minGap = Infinity;
      let side = false;
      for (let x = 0; x < r.ai.length; x++) {
        for (let y = x + 1; y < r.ai.length; y++) {
          const a = r.ai[x], b = r.ai[y];
          const d = Math.abs(b.dist - a.dist);
          const lat = Math.abs(b.lateral - a.lateral);
          if (d < 6 && lat < 2.6) side = true;
          if (d < 45) { minGap = Math.min(minGap, d); maxLateralPair = Math.max(maxLateralPair, lat); }
        }
      }
      if (side) sideBySideFrames++;
      if (Number.isFinite(minGap)) { minGapSum += minGap; minGapSamples++; }
      if (r.ai.every((a) => a.finished)) break;
    }

    const final = r.ai.map((a) => ({
      name: a.name,
      gridDist: a.dist,
      finishTime: a.finishTime,
      finished: a.finished,
      pace: +a.pace.toFixed(3)
    })).sort((a, b) => (a.finishTime ?? Infinity) - (b.finishTime ?? Infinity));
    const finishOrder = final.map((a) => a.name);
    return {
      gridOrder,
      finishOrder,
      gridPace: grid.map((g) => `${g.name}:${g.pace.toFixed(3)}`),
      final,
      swaps,
      leaderChanges,
      sideBySidePct: +((sideBySideFrames / totalFrames) * 100).toFixed(1),
      avgMinGap: +(minGapSum / Math.max(1, minGapSamples)).toFixed(1),
      raceTime: +(r.time / 1000).toFixed(1),
      errors: []
    };
  });
  result.errors = errors;
  out.push(result);
  console.log(`RACE ${raceNo + 1}: grid=${result.gridOrder.join(',')} finish=${result.finishOrder.join(',')} swaps=${result.swaps.length} leaders=${result.leaderChanges} sideBySide=${result.sideBySidePct}% avgGap=${result.avgMinGap}m time=${result.raceTime}s`);
  console.log('  pace:', result.gridPace.join(' '));
  if (result.swaps.length) console.log('  swaps:', result.swaps.slice(0, 12).map((s) => `${s.t}s ${s.gained}>${s.lost}`).join(', '));
  if (errors.length) console.log('  ERRORS:', errors);
  await page.close();
}

writeFileSync('/tmp/opencode/sim-result.json', JSON.stringify(out, null, 2));
await browser.close();

