import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

process.env.DISPLAY = ':0';
const browser = await chromium.launch({
  headless: false,
  args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface']
});
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(() => {
  localStorage.setItem('apexink.ai', '5');
  localStorage.setItem('apexink.laps', '5');
});
await page.goto('http://localhost:3000/?demo=race&go=1&track=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });

await page.evaluate(() => {
  setInterval(() => {
    const A = window.__apex;
    const race = A.race;
    if (!race || race.state !== 'racing') return;
    const p = race.player;
    const N = race.track.N;
    const idx = (p.lastIndex + 26) % N;
    const s = race.track.samples[idx];
    const desired = Math.atan2(s.x - p.pos.x, s.z - p.pos.z);
    let diff = desired - p.yaw;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    A.setDemoInput({ left: diff > 0.015, right: diff < -0.015 });
  }, 16);
});

const starts = [6, 16, 32, 55];
let prev = 0;
for (let i = 0; i < starts.length; i++) {
  await page.waitForTimeout((starts[i] - prev) * 1000);
  prev = starts[i];
  const status = await page.evaluate(() => {
    const r = window.__apex.race;
    return {
      state: r.state,
      time: +(r.time / 1000).toFixed(1),
      playerPos: r.player.progressDist.toFixed(0),
      ai: r.ai.map((a) => ({ n: a.name, d: Math.round(a.dist), sp: Math.round(a.speed * 3.6), lat: +a.lateral.toFixed(1) }))
    };
  });
  console.log('--', status.time, status.state, 'player', status.playerPos, JSON.stringify(status.ai));
  await page.screenshot({ path: `/tmp/opencode/shots/race-${i}.jpg`, type: 'jpeg', quality: 78 });
}
console.log('ERRORS:', errors);
await browser.close();

import { createRequire } from 'node:module';
import { writeFileSync } from 'node:fs';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
process.env.DISPLAY = ':0';
const browser = await chromium.launch({ headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(() => {
  localStorage.setItem('apexink.ai', '5');
  localStorage.setItem('apexink.laps', '3');
  localStorage.setItem('apexink.difficulty', 'pro');
});
await page.goto('http://localhost:3000/?demo=race&go=1&track=2', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });
const result = await page.evaluate(() => {
  const A = window.__apex;
  const r = A.race;
  r.world.update = () => {};
  const checkpoints = [];
  const started = performance.now();
  for (let i = 0; i < 20000 && r.state === 'racing'; i++) {
    const p = r.player;
    if (!p.finished) {
      const idx = (p.lastIndex + 26) % r.track.N;
      const s = r.track.samples[idx];
      const desired = Math.atan2(s.x - p.pos.x, s.z - p.pos.z);
      let diff = desired - p.yaw;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      A.setDemoInput({ left: diff > 0.015, right: diff < -0.015 });
    }
    A.tick(1 / 30);
    if (i % 30 === 0) {
      checkpoints.push({
        t: +(r.time / 1000).toFixed(1),
        player: Math.round(r.player.progressDist),
        leader: r.ai.slice().sort((a, b) => b.dist - a.dist)[0]?.name,
        aiDists: r.ai.map((a) => Math.round(a.dist))
      });
    }
  }
  const playerTime = r.player.finishTime;
  return {
    state: r.state,
    playerFinished: r.player.finished,
    playerTime,
    laps: r.player.lapsCompleted,
    finalOrder: r.ai.map((a) => ({ n: a.name, t: a.finishTime, f: a.finished })).sort((a, b) => (a.t ?? 1e12) - (b.t ?? 1e12)),
    bestLap: r.player.bestLap,
    checkpoints: checkpoints.filter((c, i) => i % 4 === 0).slice(-12),
    realTime: Math.round(performance.now() - started)
  };
});
console.log(JSON.stringify(result, null, 2));
console.log('ERRORS:', errors);
await browser.close();

