import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
process.env.DISPLAY = ':0';
const browser = await chromium.launch({ headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(() => {
  localStorage.setItem('apexink.ai', '9');
  localStorage.setItem('apexink.laps', '3');
});
await page.goto('http://localhost:3000/?demo=race&go=1&track=0', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });
await page.evaluate(() => { window.__apex.race.cameraMode = 1; });
await page.waitForTimeout(2600);
await page.screenshot({ path: '/tmp/opencode/shots/pack-a.jpg', type: 'jpeg', quality: 80 });
await page.waitForTimeout(2600);
await page.screenshot({ path: '/tmp/opencode/shots/pack-b.jpg', type: 'jpeg', quality: 80 });
const info = await page.evaluate(() => {
  const r = window.__apex.race;
  const rows = r.ai.map((a) => ({ n: a.name, d: Math.round(a.dist), lat: +a.lateral.toFixed(1), sp: Math.round(a.speed * 3.6) }));
  return { t: +(r.time / 1000).toFixed(1), rows };
});
console.log(JSON.stringify(info));
console.log('ERRORS:', errors);
await browser.close();

