// shuffled so nobody inherits a result from qualifying: the order has to be
// settled on track. Pace is dealt out as a spread ladder, so there is always
// a genuinely quick car and a genuinely slow one, and the quick one has to
// pass people to win.
const paceLadder = r.ai.length > 1
  ? r.ai.map((_, i) => 0.945 + (i / (r.ai.length - 1)) * 0.103)
  : [0.995];
for (let i = paceLadder.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [paceLadder[i], paceLadder[j]] = [paceLadder[j], paceLadder[i]];
}
r.ai.forEach((a, i) => {
  a.pace = paceLadder[i] + (Math.random() - 0.5) * 0.01;
  a.slowBias = 0.985 + Math.random() * 0.03;
  a.fastBias = 0.985 + Math.random() * 0.03;
  a.launch = 0.95 + Math.random() * 0.22;
});
// Split the field by pace and put the quicker half behind the slower half,
// with both halves shuffled. Nobody inherits a result at lights-out, and the
// fast cars always have someone to hunt down, but the grid is not a mirror.
const shuffleInPlace = (list) => {
  for (let i = list.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [list[i], list[j]] = [list[j], list[i]];
  }
  return list;
};
