143: function normalizeHex(value, { allowShort = true } = {}) {
144:   if (typeof value !== 'string') return null;
145:   let hex = value.trim().replace(/^#/, '');
146:   if (!/^[0-9a-f]+$/i.test(hex)) return null;
147:   if (allowShort && hex.length === 3) hex = hex.split('').map((c) => c + c).join('');
148:   if (hex.length !== 6) return null;
149:   return `#${hex.toUpperCase()}`;
150: }
151: 
152: function hexToInt(hex) { return parseInt(hex.slice(1), 16); }
