333: function drawMenuMinimap(last) {
334:   const canvas = dom.menuMinimap;
335:   const ctx = canvas.getContext('2d');
336:   const w = canvas.width, h = canvas.height;
337:   ctx.clearRect(0, 0, w, h);
338:   ctx.fillStyle = 'rgba(5,7,10,.4)';
339:   ctx.fillRect(0, 0, w, h);
340: 
341:   // faint grid
342:   ctx.strokeStyle = 'rgba(255,255,255,.035)';
343:   ctx.lineWidth = 1;
344:   for (let x = 20; x < w; x += 42) {
345:     ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke();
346:   }
347:   for (let y = 16; y < h; y += 42) {
348:     ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke();
349:   }
350: 
351:   if (!last) {
352:     ctx.save();
353:     ctx.translate(w / 2, h / 2);
354:     ctx.setLineDash([4, 10]);
355:     ctx.strokeStyle = 'rgba(255,77,31,.28)';
356:     ctx.lineWidth = 1.5;
357:     ctx.beginPath();
358:     ctx.ellipse(0, 0, w * 0.33, h * 0.27, -0.18, 0, TAU);
359:     ctx.stroke();
360:     ctx.setLineDash([]);
361:     ctx.strokeStyle = 'rgba(255,255,255,.08)';
362:     ctx.beginPath(); ctx.moveTo(-9, 0); ctx.lineTo(9, 0); ctx.moveTo(0, -9); ctx.lineTo(0, 9); ctx.stroke();
363:     ctx.restore();
364:     return;
365:   }
366: 
367:   const preview = analyzePreview(last.points, { targetLength: 1900 });
368:   if (!preview.prepared.length) return;
369:   let minX = Infinity, minY = Infinity, maxX = -Infinity, maxY = -Infinity;
370:   for (const p of preview.prepared) {
371:     minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x);
372:     minY = Math.min(minY, p.y); maxY = Math.max(maxY, p.y);
373:   }
374:   const pad = 30;
375:   const scale = Math.min((w - pad * 2) / (maxX - minX || 1), (h - pad * 2) / (maxY - minY || 1));
376:   const ox = (w - (maxX - minX) * scale) / 2 - minX * scale;
377:   const oy = (h - (maxY - minY) * scale) / 2 - minY * scale;
378:   const map = (p) => ({ x: p.x * scale + ox, y: p.y * scale + oy });
379: 
380:   ctx.save();
381:   ctx.lineJoin = 'round';
382:   ctx.lineCap = 'round';
383:   ctx.beginPath();
384:   preview.prepared.forEach((p, i) => {
385:     const q = map(p);
386:     if (i === 0) ctx.moveTo(q.x, q.y); else ctx.lineTo(q.x, q.y);
387:   });
388:   ctx.closePath();
389:   ctx.strokeStyle = 'rgba(255,77,31,.16)';
390:   ctx.lineWidth = 13;
391:   ctx.shadowColor = 'rgba(255,77,31,.7)';
392:   ctx.shadowBlur = 18;
393:   ctx.stroke();
394:   ctx.shadowBlur = 0;
395:   ctx.strokeStyle = 'rgba(7,9,12,.9)';
396:   ctx.lineWidth = 7;
397:   ctx.stroke();
398:   ctx.strokeStyle = '#f3efe5';
399:   ctx.lineWidth = 2.4;
400:   ctx.stroke();
401: 
402:   // start marker
403:   const start = map(preview.prepared[0]);
404:   ctx.fillStyle = '#ff4d1f';
405:   ctx.beginPath();
406:   ctx.arc(start.x, start.y, 3.5, 0, TAU);
407:   ctx.fill();
408:   ctx.strokeStyle = 'rgba(255,77,31,.8)';
409:   ctx.lineWidth = 1;
410:   ctx.beginPath();
411:   ctx.arc(start.x, start.y, 8, 0, TAU);
412:   ctx.stroke();
413:   ctx.restore();
414: }
