819: /* ═══════════════════════════════════════════════════════════════════
820:    Smoke / dust particles
821:    ═══════════════════════════════════════════════════════════════════ */
822: class SmokeSystem {
823:   constructor(scene) {
824:     this.count = 260;
825:     this.cursor = 0;
826:     this.positions = new Float32Array(this.count * 3);
827:     this.colors = new Float32Array(this.count * 3);
828:     this.sizes = new Float32Array(this.count);
829:     this.alphas = new Float32Array(this.count);
830:     this.life = new Float32Array(this.count);
831:     this.maxLife = new Float32Array(this.count);
832:     this.vel = new Float32Array(this.count * 3);
833:     this.baseSize = new Float32Array(this.count);
834:     for (let i = 0; i < this.count; i++) {
835:       this.positions[i * 3 + 1] = -999;
836:       this.alphas[i] = 0;
837:     }
838:     const geo = new THREE.BufferGeometry();
839:     geo.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
840:     geo.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
841:     geo.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
842:     geo.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
843:     this.geo = geo;
844:     this.material = new THREE.ShaderMaterial({
845:       transparent: true,
846:       depthWrite: false,
847:       vertexShader: `
848:         attribute float aSize;
849:         attribute float aAlpha;
850:         attribute vec3 aColor;
851:         varying float vAlpha;
852:         varying vec3 vColor;
853:         void main() {
854:           vAlpha = aAlpha;
855:           vColor = aColor;
856:           vec4 mv = modelViewMatrix * vec4(position, 1.0);
857:           gl_PointSize = aSize * (340.0 / max(1.0, -mv.z));
858:           gl_Position = projectionMatrix * mv;
859:         }
860:       `,
861:       fragmentShader: `
862:         varying float vAlpha;
863:         varying vec3 vColor;
864:         void main() {
865:           float d = length(gl_PointCoord - vec2(0.5));
866:           if (d > 0.5) discard;
867:           gl_FragColor = vec4(vColor, vAlpha * smoothstep(0.5, 0.08, d));
868:         }
869:       `
870:     });
871:     this.points = new THREE.Points(geo, this.material);
872:     this.points.frustumCulled = false;
873:     scene.add(this.points);
874:     this.dirty = false;
875:   }
876: 
877:   emit(x, y, z, color, size = 0.55, life = 1.1, spread = 1.4) {
878:     const i = this.cursor;
879:     this.cursor = (this.cursor + 1) % this.count;
880:     this.positions[i * 3] = x + (Math.random() - 0.5) * 0.5;
881:     this.positions[i * 3 + 1] = y + Math.random() * 0.2;
882:     this.positions[i * 3 + 2] = z + (Math.random() - 0.5) * 0.5;
883:     this.colors[i * 3] = color.r;
884:     this.colors[i * 3 + 1] = color.g;
885:     this.colors[i * 3 + 2] = color.b;
886:     this.vel[i * 3] = (Math.random() - 0.5) * spread;
887:     this.vel[i * 3 + 1] = 0.4 + Math.random() * spread;
888:     this.vel[i * 3 + 2] = (Math.random() - 0.5) * spread;
889:     this.life[i] = life;
890:     this.maxLife[i] = life;
891:     this.baseSize[i] = size;
892:     this.sizes[i] = size;
893:     this.alphas[i] = 0.5;
894:     this.dirty = true;
895:   }
896: 
897:   update(dt) {
898:     for (let i = 0; i < this.count; i++) {
899:       if (this.life[i] <= 0) continue;
900:       this.life[i] -= dt;
901:       if (this.life[i] <= 0) {
902:         this.alphas[i] = 0;
903:         this.positions[i * 3 + 1] = -999;
904:         this.dirty = true;
905:         continue;
906:       }
907:       const k = this.life[i] / this.maxLife[i];
908:       this.positions[i * 3] += this.vel[i * 3] * dt;
909:       this.positions[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
910:       this.positions[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
911:       this.vel[i * 3] *= 0.985;
912:       this.vel[i * 3 + 2] *= 0.985;
913:       this.vel[i * 3 + 1] += dt * 0.2;
914:       this.sizes[i] = this.baseSize[i] * (1.6 - k * 0.6);
915:       this.alphas[i] = k * 0.42;
916:       this.dirty = true;
917:     }
918:     if (this.dirty) {
919:       this.geo.attributes.position.needsUpdate = true;
920:       this.geo.attributes.aColor.needsUpdate = true;
921:       this.geo.attributes.aSize.needsUpdate = true;
922:       this.geo.attributes.aAlpha.needsUpdate = true;
923:       this.dirty = false;
924:     }
925:   }
926: 
927:   reset() {
928:     for (let i = 0; i < this.count; i++) {
929:       this.life[i] = 0;
930:       this.alphas[i] = 0;
931:       this.positions[i * 3 + 1] = -999;
932:     }
933:     this.geo.attributes.position.needsUpdate = true;
934:     this.geo.attributes.aAlpha.needsUpdate = true;
935:     this.cursor = 0;
936:   }
937: 
938:   dispose() {
939:     this.geo.dispose();
940:     this.material.dispose();
941:     this.points.parent?.remove(this.points);
942:   }
943: }
