945: /* ═══════════════════════════════════════════════════════════════════
946:    Race setup
947:    ═══════════════════════════════════════════════════════════════════ */
948: const GRID_GAP = 11;
949: const GRID_FIRST = 10;
950: const GRID_STAGGER = 5.2;
951: const GRID_LATERAL = 2.75;
952: 
953: // Proper staggered grid: two cars per row, one either side of the centre line,
954: // with the right-hand car a few metres further back. Slot order is decided by
955: // the caller, so grid position and driver pace stay independent.
956: function gridDistance(slot) {
957:   const row = Math.floor(slot / 2);
958:   const col = slot % 2;
959:   return -(GRID_FIRST + row * GRID_GAP + col * GRID_STAGGER);
960: }
961: 
962: function gridPose(slot) {
963:   const dist = gridDistance(slot);
964:   const lateral = (slot % 2 === 0 ? -1 : 1) * GRID_LATERAL;
965:   const s = sampleAtDistance(race.track, dist);
966:   return {
967:     x: s.x + s.nx * lateral,
968:     z: s.z + s.nz * lateral,
969:     yaw: Math.atan2(s.tx, s.tz),
970:     lateral,
971:     dist,
972:     s
973:   };
974: }
