980: // Invisible timing gates spaced around the lap. They are never rendered: they
981: // simply stop the nearest-point lookup from mistaking a nearby part of the
982: // circuit for the part the player is actually racing on.
983: function createRaceCheckpoints(track) {
984:   const count = clamp(Math.round(track.length / 55), 20, 48);
985:   const spacing = track.length / count;
986:   return Array.from({ length: count }, (_, i) => {
987:     const s = sampleAtDistance(track, i * spacing);
988:     return { dist: i * spacing, x: s.x, z: s.z, tx: s.tx, tz: s.tz, nx: s.nx, nz: s.nz };
989:   });
990: }
