1112: function resetRaceState() {
1113:   const r = race;
1114:   const p = r.player;
1115: 
1116:   // The player starts behind the selected AI field on a fresh staggered grid.
1117:   const playerGridSlot = r.ai.length;
1118:   const pose = gridPose(playerGridSlot);
1119:   p.pos = { x: pose.x, z: pose.z };
1120:   p.vel = { x: 0, z: 0 };
1121:   p.yaw = pose.yaw;
1122:   p.lateral = pose.lateral;
1123:   p.steer = 0; p.throttle = 0; p.brake = 0;
1124:   p.vLong = 0; p.vLat = 0; p.prevVLong = 0; p.yawRate = 0;
1125:   p.offroad = false; p.offTimer = 0;
1126:   p.lapsCompleted = 0; p.lapStart = 0;
1127:   p.sectors = [false, false, false];
1128:   p.bestLap = readBest(r.track.seed);
1129:   p.lastLap = null; p.topSpeed = 0;
1130:   p.finished = false; p.finishTime = null; p.finishPosition = r.ai.length + 1;
1131:   p.drs = false; p.trackDist = 0;
1132:   p.assistState = 'auto';
1133:   p.history = [];
1134:   const startIndex = r.locator.nearest(pose.x, pose.z).index;
1135:   p.lastIndex = startIndex;
1136:   p.progressDist = pose.dist;
1137:   p.cpNext = 0;
1138:   p.cpArmed = false;
1139:   p.sNorm = (startIndex % r.track.N) / r.track.N;
1140:   r.camYaw = pose.yaw;
1141:   r.shakeT = 0;
1142:   r.impactShake = 0;
