1411: function gapToLeaderSeconds(leader, progress, speed) {
1412:   const history = leader.history;
1413:   if (!history || history.length < 2) return 0;
1414:   const first = history[0];
1415:   const last = history[history.length - 1];
1416:   if (progress >= last.p) return 0;
1417:   if (progress < first.p) {
1418:     // Before the leader's first sample (the grid): no elapsed race time yet.
1419:     if (race.time < 600) return 0;
1420:     const metres = (first.p - progress) * race.track.length;
1421:     return metres / Math.max(24, speed);
1422:   }
1423:   // Binary search for the first timeline sample at or beyond this progress.
1424:   let lo = 0, hi = history.length - 1;
1425:   while (lo < hi) {
1426:     const mid = (lo + hi) >> 1;
1427:     if (history[mid].p >= progress) hi = mid; else lo = mid + 1;
1428:   }
1429:   const b = history[lo];
1430:   const a = history[Math.max(0, lo - 1)];
