1561:       // Player throttle overrides the speed planner so you can chase a faster lap.
1562:       throttleDemand = 1;
1563:       assistState = 'manual';
1564:     } else if (!handbrake) {
1565:       const auto = autoDriveDemand(p, race.track);
1566:       throttleDemand = auto.throttle;
1567:       brakeDemand = auto.brake;
1568:       assistState = auto.brake > 0.15 ? 'auto-brake' : 'auto';
1569:     } else {
1570:       assistState = 'manual';
1571:     }
1572:   }
1573:   p.assistState = assistState;
1574: 
1575:   p.throttle = damp(p.throttle, throttleDemand, 11, dt);
1576:   p.brake = damp(p.brake, brakeDemand, 16, dt);
1577:   p.steer = damp(p.steer, controls.steer, HANDLING.steerResponse, dt);
1578: 
1579:   const speed0 = Math.hypot(p.vel.x, p.vel.z);
1580:   const f0x = Math.sin(p.yaw), f0z = Math.cos(p.yaw);
1581:   const vLong0 = p.vel.x * f0x + p.vel.z * f0z;
1582: 
1583:   const maxSteer = lerp(
1584:     HANDLING.steerLowSpeed,
1585:     HANDLING.steerHighSpeed,
1586:     clamp(speed0 / HANDLING.steerSpeedRef, 0, 1)
1587:   );
1588:   const steerAngle = p.steer * maxSteer;
1589:   const gripAccel = p.offroad
1590:     ? HANDLING.gripOffroad
1591:     : handbrake
1592:       ? HANDLING.gripHandbrake
1593:       : p.onKerb
1594:         ? HANDLING.gripKerb
1595:         : HANDLING.gripTrack;
1596:   const maxYaw = gripAccel / Math.max(4, speed0);
1597:   let yawTarget = (vLong0 / 3.05) * Math.tan(steerAngle);
1598:   if (handbrake) yawTarget *= 1.55;
1599:   yawTarget = clamp(yawTarget, -maxYaw, maxYaw);
1600:   p.yawRate = damp(p.yawRate, yawTarget, HANDLING.yawResponse, dt);
1601:   p.yaw += p.yawRate * dt;
1602:   p.yaw = ((p.yaw + Math.PI) % TAU + TAU) % TAU - Math.PI;
1603: 
1604:   const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
1605:   const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
1606: 
1607:   let vLong = p.vel.x * fx + p.vel.z * fz;
1608:   let vLat = p.vel.x * rx + p.vel.z * rz;
1609: 
1610:   const drs = race.state === 'racing' && vLong > 55 && Math.abs(p.lastK || 0) < 1 / 420 && p.throttle > 0.35;
1611:   p.drs = drs;
1612: 
1613:   let accel = 0;
1614:   if (p.throttle > 0.01) {
1615:     const maxSpeed = drs ? 96 : 90;
1616:     const ratio = clamp(vLong / maxSpeed, -1, 1);
1617:     const engine = 18.5 * Math.max(0, 1 - ratio * ratio);
1618:     accel += engine * p.throttle * (p.offroad ? HANDLING.offroadPower : 1);
1619:   }
1620:   if (p.brake > 0.01) {
1621:     if (vLong > 0.35) accel -= 33 * p.brake;
1622:     else accel -= 6.8 * p.brake;
1623:   }
1624:   if (handbrake) accel -= 9;
1625:   const dragCoef = drs ? 0.000165 : 0.00022;
1626:   const drag = dragCoef * vLong * Math.abs(vLong) + 0.6 * Math.sign(vLong) + (p.offroad ? HANDLING.offroadDrag : 0);
1627:   accel -= drag;
1628:   vLong += accel * dt;
1629:   if (vLong < -12) vLong = -12;
1630:   if (p.throttle < 0.02 && p.brake < 0.02 && !handbrake && Math.abs(vLong) < 0.2) vLong = 0;
1631: 
1632:   const sideGrip = p.offroad
1633:     ? HANDLING.sideGripOffroad
1634:     : handbrake
1635:       ? HANDLING.sideGripHandbrake
1636:       : p.onKerb
1637:         ? HANDLING.sideGripKerb
1638:         : HANDLING.sideGripTrack;
1639:   vLat *= Math.exp(-sideGrip * dt);
1640: 
1641:   p.vLong = vLong;
1642:   p.vLat = vLat;
1643:   p.vel.x = fx * vLong + rx * vLat;
1644:   p.vel.z = fz * vLong + rz * vLat;
1645:   p.pos.x += p.vel.x * dt;
1646:   p.pos.z += p.vel.z * dt;
1647: 
1648:   const near = nearestTrackSample(tr, p.pos.x, p.pos.z, p.lastIndex);
1649:   const sample = tr.samples[near.index];
1650:   p.lastIndex = near.index;
1651:   p.sNorm = (near.index % tr.N) / tr.N;
1652:   p.trackDist = near.dist;
1653:   p.lateral = (p.pos.x - sample.x) * sample.nx + (p.pos.z - sample.z) * sample.nz;
1654:   p.lastK = sample.k;
1655:   p.offroad = near.dist > tr.halfWidth + 1.15;
1656:   p.onKerb = !p.offroad && near.dist > tr.halfWidth - 0.55 && near.dist < tr.halfWidth + 1.6;
1657:   if (p.offroad) {
1658:     p.offTimer += dt * (near.dist > tr.halfWidth + 25 ? 2 : 1);
1659:   } else {
1660:     p.offTimer = Math.max(0, p.offTimer - dt * 2.5);
1661:   }
1662:   if (race.state === 'racing' && p.offTimer > 2.7) recoverPlayer();
1663: 
1664:   const kmh = Math.abs(vLong) * 3.6;
1665:   if (race.state === 'racing') p.topSpeed = Math.max(p.topSpeed, kmh);
1666: }
