1668: function updatePlayerVisual(dt) {
1669:   const p = race.player;
1670:   const car = race.playerCar;
1671:   car.root.position.set(p.pos.x, 0, p.pos.z);
1672:   car.root.rotation.y = p.yaw;
1673: 
1674:   const longAccel = (p.vLong - p.prevVLong) / Math.max(dt, 0.001);
1675:   p.prevVLong = p.vLong;
1676:   car.body.rotation.x = damp(car.body.rotation.x, clamp(-longAccel * 0.0022, -0.055, 0.055), 7, dt);
1677:   car.body.rotation.z = damp(car.body.rotation.z, clamp(p.vLong * p.yawRate * 0.0032, -0.07, 0.07), 7, dt);
1678: 
1679:   const steerVisual = p.steer * lerp(
1680:     HANDLING.steerLowSpeed * 0.82,
1681:     HANDLING.steerHighSpeed * 1.2,
1682:     clamp(Math.abs(p.vLong) / HANDLING.steerSpeedRef, 0, 1)
1683:   );
1684:   for (const w of car.wheels) {
1685:     w.spin.rotation.x += (p.vLong / w.radius) * dt;
1686:     if (w.front) w.steer.rotation.y = damp(w.steer.rotation.y, steerVisual, 18, dt);
1687:   }
1688:   car.setBrake(p.brake > 0.08 || race.state === 'finished');
1689:   car.setDRS(p.drs);
1690: 
1691:   // tyre smoke and grass dust
1692:   const slip = Math.abs(p.vLat);
1693:   const speed = Math.abs(p.vLong);
1694:   const rate = p.offroad && speed > 4 ? 42 : (slip > 2.4 && speed > 6 ? 26 : 0);
1695:   if (rate && race.state !== 'countdown') {
1696:     emitAccum += dt * rate;
1697:     while (emitAccum >= 1) {
1698:       emitAccum -= 1;
1699:       const fx = Math.sin(p.yaw), fz = Math.cos(p.yaw);
1700:       const rx = Math.cos(p.yaw), rz = -Math.sin(p.yaw);
1701:       const side = Math.random() > 0.5 ? 1 : -1;
1702:       const x = p.pos.x - fx * 1.65 + rx * side * 0.85;
1703:       const z = p.pos.z - fz * 1.65 + rz * side * 0.85;
1704:       const color = p.offroad ? DUST_COLOR : SMOKE_COLOR;
1705:       race.smoke.emit(x, 0.22, z, color, p.offroad ? 0.9 : 0.7, p.offroad ? 1.25 : 1.0, p.offroad ? 2.4 : 1.6);
1706:     }
1707:   }
