1710: function nearestTrackSample(track, x, z, hint = -1, windowMeters = 26) {
1711:   const N = track.N;
1712:   let best = -1;
1713:   let bestD = Infinity;
1714:   if (Number.isInteger(hint) && hint >= 0 && hint < N) {
1715:     const span = Math.max(6, Math.round(windowMeters / track.step));
1716:     for (let k = -span; k <= span; k++) {
1717:       const i = (hint + k + N) % N;
1718:       const s = track.samples[i];
1719:       const d = (s.x - x) ** 2 + (s.z - z) ** 2;
1720:       if (d < bestD) { bestD = d; best = i; }
1721:     }
1722:     // If the car is well off the road (or has been recovered), fall back to the
1723:     // spatial lookup so it can always find its way back to the nearest asphalt.
1724:     if (best >= 0 && bestD > (track.halfWidth + 36) ** 2) {
1725:       const global = race.locator.nearest(x, z);
1726:       const d = global.dist * global.dist;
1727:       if (global.index >= 0 && d < bestD) { bestD = d; best = global.index; }
1728:     }
1729:   }
1730:   if (best < 0) {
1731:     const global = race.locator.nearest(x, z);
1732:     best = global.index >= 0 ? global.index : 0;
1733:     bestD = global.dist * global.dist;
1734:   }
1735:   return { index: best, dist: Math.sqrt(bestD) };
1736: }
1737: 
1738: function trackDistanceAt(track, index, x, z) {
1739:   const s = track.samples[index];
1740:   const along = (x - s.x) * s.tx + (z - s.z) * s.tz;
1741:   return (s.s ?? index * track.step) + clamp(along, -track.step, track.step);
1742: }
1743: 
1744: function unwrapTrackDistance(candidate, reference, length) {
1745:   let out = candidate;
1746:   const half = length * 0.5;
1747:   while (out - reference > half) out -= length;
1748:   while (out - reference < -half) out += length;
1749:   return out;
1750: }
1751: 
1752: function recoverPlayer(showToast = true) {
1753:   const p = race.player;
1754:   const near = nearestTrackSample(race.track, p.pos.x, p.pos.z, p.lastIndex);
1755:   const s = race.track.samples[near.index];
1756:   p.pos = { x: s.x, z: s.z };
1757:   p.vel = { x: 0, z: 0 };
1758:   p.vLong = 0; p.vLat = 0;
1759:   p.yaw = Math.atan2(s.tx, s.tz);
1760:   p.offroad = false;
1761:   p.offTimer = 0;
1762:   p.lastIndex = near.index;
1763:   p.sNorm = (near.index % race.track.N) / race.track.N;
1764:   p.progressDist = unwrapTrackDistance(trackDistanceAt(race.track, near.index, s.x, s.z), p.progressDist, race.track.length);
1765:   race.locator.lastIndex = near.index;
1766:   // Cut the camera with the car rather than letting it swoop across the
1767:   // circuit to the recovery point.
1768:   race.camYaw = p.yaw;
1769:   race.cameraReady = false;
1770:   race.camLook.set(s.x + Math.sin(p.yaw) * 7, 0.92, s.z + Math.cos(p.yaw) * 7);
1771:   race.smoke.reset();
1772:   if (showToast) {
1773:     toast('Recovered to the racing line');
1774:     audio.tone(330, 0.1, 0.04, 'triangle');
1775:   }
1776: }
