1778: /* ═══════════════════════════════════════════════════════════════════
1779:    Lap logic
1780:    ═══════════════════════════════════════════════════════════════════ */
1781: function completeLap() {
1782:   const p = race.player;
1783:   const lapTime = race.time - p.lapStart;
1784:   if (lapTime > 3000) {
1785:     p.lastLap = lapTime;
1786:     if (!p.bestLap || lapTime < p.bestLap) {
1787:       p.bestLap = lapTime;
1788:       writeBest(race.track.seed, lapTime);
1789:       toast(`NEW BEST LAP · ${formatTime(lapTime)}`);
1790:     }
1791:   }
1792:   p.lapsCompleted++;
1793:   p.lapStart = race.time;
1794:   p.sectors = [false, false, false];
1795:   if (p.lapsCompleted >= race.totalLaps) {
1796:     finishRace();
1797:   } else if (p.lapsCompleted === race.totalLaps - 1) {
1798:     showRaceMessage('FINAL LAP', 'EVERYTHING YOU HAVE', 2300, true);
1799:     audio.tone(880, 0.18, 0.06, 'triangle');
1800:   } else {
1801:     showRaceMessage(`LAP ${p.lapsCompleted + 1} / ${race.totalLaps}`, 'KEEP IT CLEAN', 1900);
1802:     audio.tone(660, 0.1, 0.04, 'triangle');
1803:   }
1804: }
