1806: function updatePlayerProgress(dt) {
1807:   const p = race.player;
1808:   if (p.finished) return;
1809:   const tr = race.track;
1810:   const L = tr.length;
1811:   const near = nearestTrackSample(tr, p.pos.x, p.pos.z, p.lastIndex);
1812:   const candidate = unwrapTrackDistance(
1813:     trackDistanceAt(tr, near.index, p.pos.x, p.pos.z),
1814:     p.progressDist,
1815:     L
1816:   );
1817: 
1818:   // A car can only advance a sensible distance in one physics step. Clamping
1819:   // rejected huge jumps from nearby track sections while still letting the
1820:   // progress catch up after a recovery.
1821:   const allowed = Math.max(16, Math.abs(p.vLong) * Math.max(dt, 0.001) * 4 + 3);
1822:   const delta = candidate - p.progressDist;
1823:   p.progressDist += Math.abs(delta) <= allowed ? delta : clamp(delta, -allowed, allowed);
1824:   p.lastIndex = near.index;
1825:   p.trackDist = near.dist;
1826:   p.sNorm = (((p.progressDist % L) + L) % L) / L;
1827: 
1828:   // Hidden checkpoints. The lap only counts after every gate has been crossed
1829:   // in order, which keeps the timing tower honest even on circuits that fold
1830:   // back alongside themselves.
1831:   const cpCount = race.checkpoints.length;
1832:   const cpSpacing = L / cpCount;
1833:   if (p.cpArmed) {
1834:     if (p.progressDist >= (p.lapsCompleted + 1) * L) {
1835:       p.cpArmed = false;
1836:       p.cpNext = 1;
1837:       completeLap();
1838:     }
1839:   } else {
1840:     const target = p.lapsCompleted * L + p.cpNext * cpSpacing;
1841:     if (p.progressDist >= target) {
1842:       if (p.cpNext >= cpCount - 1) {
1843:         p.cpArmed = true;
1844:         p.cpNext = 0;
1845:       } else {
1846:         p.cpNext++;
1847:       }
1848:     }
1849:   }
1850: 
1851:   const lapFrac = (((p.progressDist % L) + L) % L) / L;
1852:   if (lapFrac > 0.13) p.sectors[0] = true;
1853:   if (lapFrac > 0.38) p.sectors[1] = true;
1854:   if (lapFrac > 0.64) p.sectors[2] = true;
1855: }
