1857: /* ═══════════════════════════════════════════════════════════════════
1858:    AI drivers
1859:    ═══════════════════════════════════════════════════════════════════ */
1860: /* Cars are three overlapping circles rather than one big invisible circle, so
1861:    contact happens where the bodywork actually is. When you run into another
1862:    car you scrub speed and get nudged along it — the closing speed is killed,
1863:    never reflected, so you are not fired backwards like a rubber ball. */
1864: const CONTACT = {
1865:   offsets: [1.45, 0, -1.45],
1866:   radii: [1.02, 1.06, 1.02]
1867: };
1868: const SPARK_COLOR = new THREE.Color(0xffb257);
1869: const playerCircles = new Float32Array(6);
1870: const aiCircles = new Float32Array(6);
1871: let contactCooldown = 0;
1872: 
1873: function fillCarCircles(x, z, yaw, out) {
1874:   const fx = Math.sin(yaw);
1875:   const fz = Math.cos(yaw);
1876:   for (let i = 0; i < 3; i++) {
1877:     const o = CONTACT.offsets[i];
1878:     out[i * 2] = x + fx * o;
1879:     out[i * 2 + 1] = z + fz * o;
1880:   }
1881:   return out;
1882: }
1883: 
1884: function resolveCarCollisions(dt = 1 / 60) {
1885:   const p = race.player;
1886:   const tr = race.track;
1887:   if (contactCooldown > 0) contactCooldown = Math.max(0, contactCooldown - dt);
1888: 
1889:   fillCarCircles(p.pos.x, p.pos.z, p.yaw, playerCircles);
1890: 
1891:   for (const a of race.ai) {
1892:     const ax = a.model.root.position.x;
1893:     const az = a.model.root.position.z;
1894:     const ayaw = a.model.root.rotation.y;
1895:     fillCarCircles(ax, az, ayaw, aiCircles);
1896: 
1897:     let overlap = 0;
1898:     let nx = 0;
1899:     let nz = 0;
1900:     let contactX = 0;
1901:     let contactZ = 0;
1902:     for (let i = 0; i < 3; i++) {
1903:       const px = playerCircles[i * 2];
1904:       const pz = playerCircles[i * 2 + 1];
1905:       for (let j = 0; j < 3; j++) {
1906:         const cx = aiCircles[j * 2];
1907:         const cz = aiCircles[j * 2 + 1];
1908:         const dx = px - cx;
1909:         const dz = pz - cz;
1910:         const dist = Math.hypot(dx, dz) || 0.0001;
1911:         const deep = CONTACT.radii[i] + CONTACT.radii[j] - dist;
1912:         if (deep <= overlap) continue;
1913:         overlap = deep;
1914:         nx = dx / dist;
1915:         nz = dz / dist;
1916:         contactX = (px + cx) * 0.5;
1917:         contactZ = (pz + cz) * 0.5;
1918:       }
1919:     }
1920:     if (overlap <= 0) continue;
1921: 
1922:     const aFx = Math.sin(ayaw);
1923:     const aFz = Math.cos(ayaw);
1924:     const aRx = Math.cos(ayaw);
1925:     const aRz = -Math.sin(ayaw);
1926:     const aiVx = aFx * a.speed;
1927:     const aiVz = aFz * a.speed;
1928:     const relVx = p.vel.x - aiVx;
1929:     const relVz = p.vel.z - aiVz;
1930:     const vn = relVx * nx + relVz * nz;
1931: 
1932:     // Split the positional separation between the two cars. The player is
1933:     // shoved sideways off the other car; the AI takes the rest as a shove
1934:     // along the track, so you can lean on it and muscle past instead of
1935:     // bouncing back down the road.
1936:     const push = Math.min(overlap, 0.7);
1937:     p.pos.x += nx * push * 0.55;
1938:     p.pos.z += nz * push * 0.55;
1939: 
1940:     const s = sampleAtDistance(tr, a.dist);
1941:     const shove = push * 0.5;
1942:     a.dist += (s.tx * -nx + s.tz * -nz) * shove;
1943:     const latLimit = Math.max(2.4, tr.halfWidth - 1.6);
1944:     a.lateral = clamp(a.lateral + (s.nx * -nx + s.nz * -nz) * shove, -latLimit, latLimit);
1945: 
1946:     // Contact is always worth a small scrub and a side-step, even when the
1947:     // relative speed is tiny, so cars rub instead of sticking together.
1948:     const fx = Math.sin(p.yaw);
1949:     const fz = Math.cos(p.yaw);
1950:     const rx = Math.cos(p.yaw);
1951:     const rz = -Math.sin(p.yaw);
1952:     let impact = 0;
1953:     if (vn < 0) {
1954:       impact = Math.min(1, Math.abs(vn) / 26);
1955:       // Remove only the speed heading into the other car. Whatever speed you
1956:       // carry along the contact patch stays, so you keep driving forward.
1957:       p.vel.x -= nx * vn;
1958:       p.vel.z -= nz * vn;
1959:       const tanVx = relVx - nx * vn;
1960:       const tanVz = relVz - nz * vn;
1961:       const scrub = 0.07 + impact * 0.16;
1962:       p.vel.x -= tanVx * scrub;
1963:       p.vel.z -= tanVz * scrub;
1964: 
1965:       // How square-on the hit is: 1 = straight up the gearbox, 0 = pure
1966:       // side swipe. Square-on hits get a firm side-step so you peel around
1967:       // the car ahead instead of grinding along behind it.
1968:       const squareOn = Math.abs(nx * fx + nz * fz);
1969:       const sideOff = (p.pos.x - ax) * aRx + (p.pos.z - az) * aRz;
1970:       const side = Math.abs(sideOff) > 0.12 ? Math.sign(sideOff) : (p.vLat >= 0 ? 1 : -1);
1971:       const escape = (0.5 + impact * 3.2) * (0.35 + squareOn * 0.65);
1972:       p.vel.x += aRx * side * escape;
1973:       p.vel.z += aRz * side * escape;
1974: 
1975:       // A shove up the road for the car ahead, so it does not feel like a wall.
1976:       a.speed += impact * 1.8;
1977:     }
1978: 
1979:     p.vLong = p.vel.x * fx + p.vel.z * fz;
1980:     p.vLat = p.vel.x * rx + p.vel.z * rz;
1981:     // The shove changed where the player is; refresh its circles before the
1982:     // next car is tested so a three-wide squeeze resolves in one frame.
1983:     fillCarCircles(p.pos.x, p.pos.z, p.yaw, playerCircles);
1984: 
1985:     // Keep the AI model where we just shoved it so the next frame agrees.
1986:     const as = sampleAtDistance(tr, a.dist);
1987:     const ax2 = as.x + as.nx * a.lateral;
1988:     const az2 = as.z + as.nz * a.lateral;
1989:     a.model.root.position.set(ax2, 0, az2);
1990:     a.model.root.rotation.y = Math.atan2(as.tx, as.tz);
1991:     a.lastX = ax2;
1992:     a.lastZ = az2;
1993:     a.lastYaw = a.model.root.rotation.y;
1994: 
1995:     if (vn < -1.4 && contactCooldown <= 0) {
1996:       contactCooldown = 0.22;
1997:       const power = clamp(Math.abs(vn) / 24, 0.15, 1);
1998:       for (let k = 0; k < 7; k++) {
1999:         race.smoke.emit(contactX, 0.45 + Math.random() * 0.5, contactZ, SPARK_COLOR,
2000:           0.2 + Math.random() * 0.18, 0.24 + Math.random() * 0.2, 3.4);
2001:       }
2002:       race.impactShake = Math.max(race.impactShake || 0, 0.25 + power * 0.45);
2003:       audio.impact(power);
2004:     }
2005:   }
2006: }
