  localStorage.setItem('apexink.ai', String(aiCount));
  localStorage.setItem('apexink.laps', String(laps));
  localStorage.setItem('apexink.difficulty', 'pro');
}, { aiCount, laps });
await page.goto('http://localhost:3000/?demo=race&go=1&track=2', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });

const result = await page.evaluate(({ laps }) => {
  const A = window.__apex;
  const r = A.race;
  r.world.update = () => {};
  const tr = r.track;

  // Park the player far away from the circuit so only AI behaviour is measured.
  const px = tr.centerX + 900;
  const pz = tr.centerZ + 900;
  const parkPlayer = () => {
    const p = r.player;
    p.finished = true;
    p.pos.x = px; p.pos.z = pz;
    p.vel.x = 0; p.vel.z = 0;
    p.vLong = 0; p.vLat = 0;
    p.progressDist = -1e6;
  };
  parkPlayer();

  const start = r.ai.map((a) => ({ name: a.name, slotDist: Math.round(a.dist), pace: +a.pace.toFixed(4), lat: +a.lateral.toFixed(2) }));

  let swaps = 0;
  let lastOrder = null;
  let maxSameDistRun = 0;
  const sameRun = new Map();
  const samples = [];
  const eventLog = [];
  let overlapFrames = 0;
  let minGapSeen = Infinity;

  for (let i = 0; i < 20000 && r.state === 'racing'; i++) {
    parkPlayer();
    A.tick(1 / 30);

    // AI order by race distance among AI only.
    const order = r.ai.slice().sort((a, b) => b.dist - a.dist).map((a) => a.name);
    if (lastOrder) {
      if (order.join() !== lastOrder.join()) {
        swaps++;
        if (eventLog.length < 200) eventLog.push({ t: +(r.time / 1000).toFixed(1), order: order.join('>') });
      }
    }
    lastOrder = order;

    // Detect exactly-equal distances (cars glued together).
    for (const a of r.ai) {
      const key = a.name;
      let run = 0;
      for (const b of r.ai) {
        if (b === a) continue;
        if (Math.abs(a.dist - b.dist) < 0.01) { run++; }
      }
      if (run > 0) {
        const cur = (sameRun.get(key) || 0) + 1;
        sameRun.set(key, cur);
        maxSameDistRun = Math.max(maxSameDistRun, cur);
      } else sameRun.set(key, 0);
    }

    // Physical overlap between AI cars.
    for (let x = 0; x < r.ai.length; x++) {
      for (let y = x + 1; y < r.ai.length; y++) {
        const a = r.ai[x], b = r.ai[y];
        const dd = Math.hypot(a.lastX - b.lastX, a.lastZ - b.lastZ);
        if (dd < 3.2) { overlapFrames++; minGapSeen = Math.min(minGapSeen, dd); }
      }
    }

    if (i % 60 === 0) {
      const sorted = r.ai.slice().sort((a, b) => b.dist - a.dist);
      samples.push({
        t: +(r.time / 1000).toFixed(1),
        d: sorted.map((a) => `${a.name}:${Math.round(a.dist)}`).join(' '),
        lat: r.ai.map((a) => +a.lateral.toFixed(1)),
        passing: r.ai.filter((a) => a.passUntil > r.time).map((a) => `${a.name}${a.passSide > 0 ? 'R' : 'L'}`)
      });
    }
  }

  const finalOrder = r.ai.slice().sort((a, b) => b.dist - a.dist).map((a) => ({
    name: a.name,
    dist: Math.round(a.dist),
    laps: +(a.dist / tr.length).toFixed(2),
    finished: a.finished,
    pace: +a.pace.toFixed(4),
    slot: start.find((s) => s.name === a.name)?.slotDist
  }));
  return {
    trackLength: Math.round(tr.length),
    state: r.state,
    start,
    finalOrder,
    positionSwaps: swaps,
    maxSameDistFrames: maxSameDistRun,
    overlapFrames,
    minGapSeen: +minGapSeen.toFixed(2),
    eventLog,
    samples: samples.filter((_, i) => i % 2 === 0)
  };
}, { laps });

console.log(JSON.stringify(result, null, 2));
console.log('ERRORS:', errors);
await browser.close();

