import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
process.env.DISPLAY = ':0';

const aiCount = Number(process.argv[2] || 6);
const laps = Number(process.argv[3] || 3);
const track = Number(process.argv[4] || 2);
const browser = await chromium.launch({ headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(({ aiCount, laps }) => {
  localStorage.setItem('apexink.ai', String(aiCount));
  localStorage.setItem('apexink.laps', String(laps));
  localStorage.setItem('apexink.difficulty', 'pro');
}, { aiCount, laps });
await page.goto(`http://localhost:3000/?demo=race&go=1&track=${track}`, { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });

const result = await page.evaluate(({ laps }) => {
  const A = window.__apex;
  const r = A.race;
  r.world.update = () => {};
  const tr = r.track;
  const L = tr.length;

  const px = tr.centerX + 900;
  const pz = tr.centerZ + 900;
  const parkPlayer = () => {
    const p = r.player;
    p.finished = true;
    p.pos.x = px; p.pos.z = pz;
    p.vel.x = 0; p.vel.z = 0;
    p.vLong = 0; p.vLat = 0;
    p.progressDist = -1e6;
  };
  parkPlayer();

  const start = r.ai.map((a) => ({ name: a.name, slot: Math.round(a.dist), pace: +a.pace.toFixed(3) }));
  const startBySlot = [...start].sort((a, b) => b.slot - a.slot).map((s) => s.name);

  let swaps = 0;
  let lastOrder = null;
  let overlapFrames = 0;
  let minGapSeen = Infinity;
  const samples = [];
  const passEvents = [];
  const activePasses = new Map();
  let leaderCount = 1;
  let lastLeader = null;

  for (let i = 0; i < 30000; i++) {
    const done = r.ai.every((a) => a.finished);
    if (done) break;
    parkPlayer();
    A.tick(1 / 30);

    const order = r.ai.slice().sort((a, b) => b.dist - a.dist).map((a) => a.name);
    if (lastOrder && order.join() !== lastOrder.join()) {
      swaps++;
      if (order[0] !== lastLeader) leaderCount++;
    }
    lastLeader = order[0];
    lastOrder = order;

    // Log committed overtakes and whether the attacker gets ahead.
    for (const a of r.ai) {
      if (a.passUntil > r.time) {
        if (!activePasses.has(a.name)) {
          const b = a.blocker;
          if (b) activePasses.set(a.name, { t: r.time, target: b.name, gap: a.blockerGap, done: false });
        }
      } else {
        const rec = activePasses.get(a.name);
        if (rec && !rec.done) {
          const target = r.ai.find((x) => x.name === rec.target);
          rec.done = true;
          rec.success = target ? a.dist > target.dist : false;
          rec.duration = Math.round(r.time - rec.t);
          passEvents.push({ attacker: a.name, target: rec.target, gapAtCommit: Math.round(rec.gap), duration: rec.duration, success: rec.success });
          activePasses.delete(a.name);
        }
      }
    }

    for (let x = 0; x < r.ai.length; x++) {
      for (let y = x + 1; y < r.ai.length; y++) {
        const a = r.ai[x], b = r.ai[y];
        const dd = Math.hypot(a.lastX - b.lastX, a.lastZ - b.lastZ);
        if (dd < 2.1) { overlapFrames++; minGapSeen = Math.min(minGapSeen, dd); }
      }
    }

    if (i % 90 === 0) {
      const sorted = r.ai.slice().sort((a, b) => b.dist - a.dist);
      samples.push({
        t: +(r.time / 1000).toFixed(1),
        lead: sorted[0].name,
        spread: Math.round(sorted[0].dist - sorted[sorted.length - 1].dist),
        d: sorted.map((a) => Math.round(a.dist)).join(' ')
      });
    }
  }

  const finishOrder = r.ai.slice().sort((a, b) => (a.finishTime ?? 1e18) - (b.finishTime ?? 1e18));
  const finalOrder = r.ai.slice().sort((a, b) => b.dist - a.dist).map((a) => ({
    name: a.name, dist: Math.round(a.dist), finished: a.finished,
    finish: a.finishTime ? +(a.finishTime / 1000).toFixed(2) : null,
    pace: +a.pace.toFixed(3), startSlot: start.find((s) => s.name === a.name)?.slot
  }));
  const earliest = finishOrder.find((a) => a.finishTime)?.finishTime || 0;
  return {
    trackLength: Math.round(L),
    laps,
    aiCount: r.ai.length,
    startOrderBySlot: startBySlot,
    finishOrder: finishOrder.map((a) => ({ name: a.name, at: a.finishTime ? +((a.finishTime - earliest) / 1000).toFixed(2) : null, pace: +a.pace.toFixed(3) })),
    finalOrder,
    positionSwaps: swaps,
    distinctLeaders: leaderCount,
    committedPasses: passEvents.length,
    successfulPasses: passEvents.filter((p) => p.success).length,
    passEvents: passEvents.slice(0, 25),
    overlapFrames, minGapSeen: +minGapSeen.toFixed(2),
    samples
  };
}, { laps });

console.log(JSON.stringify(result, null, 2));
console.log('ERRORS:', errors);
await browser.close();

