import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
process.env.DISPLAY = ':0';

const aiCount = Number(process.argv[2] || 6);
const laps = Number(process.argv[3] || 3);
const track = Number(process.argv[4] || 2);
const browser = await chromium.launch({ headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist', '--use-angle=vulkan', '--use-vulkan=swiftshader', '--disable-vulkan-surface'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 720 } });
const errors = [];
page.on('pageerror', (e) => errors.push('PAGEERROR ' + e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push('CONSOLE ' + m.text()); });
await page.addInitScript(({ aiCount, laps }) => {
  localStorage.setItem('apexink.ai', String(aiCount));
  localStorage.setItem('apexink.laps', String(laps));
  localStorage.setItem('apexink.difficulty', 'pro');
}, { aiCount, laps });
await page.goto(`http://localhost:3000/?demo=race&go=1&track=${track}`, { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 45000 });

const result = await page.evaluate(({ laps }) => {
  const A = window.__apex;
  const r = A.race;
  r.world.update = () => {};
  const tr = r.track;
  const L = tr.length;

  // Park the player out of the way so only AI racing is measured.
  const px = tr.centerX + 900;
  const pz = tr.centerZ + 900;
  const parkPlayer = () => {
    const p = r.player;
    p.finished = true;
    p.pos.x = px; p.pos.z = pz;
    p.vel.x = 0; p.vel.z = 0;
    p.vLong = 0; p.vLat = 0;
    p.progressDist = -1e6;
  };
  parkPlayer();

  const gridOrder = r.ai.slice().sort((a, b) => b.dist - a.dist);
  const gridInfo = gridOrder.map((a, i) => ({ pos: i + 1, name: a.name, pace: +a.pace.toFixed(3), slot: Math.round(a.dist) }));
  const gridNames = gridOrder.map((a) => a.name);

  const history = [];
  const passStarts = new Map();
  const passes = [];
  let minGapSeen = Infinity;
  let overlapFrames = 0;

  for (let i = 0; i < 30000; i++) {
    if (r.ai.every((a) => a.finished)) break;
    parkPlayer();
    A.tick(1 / 30);

    // Track pass commits and success within 7s.
    for (const a of r.ai) {
      if (a.passUntil > r.time) {
        if (!passStarts.has(a.name)) {
          passStarts.set(a.name, { t: r.time, target: a.blocker?.name || null, gap: Math.round(a.blockerGap) });
        }
      } else {
        const rec = passStarts.get(a.name);
        if (rec) {
          passStarts.delete(a.name);
          const target = r.ai.find((x) => x.name === rec.target);
