    behind: a.finishTime ? +((a.finishTime - winnerTime) / 1000).toFixed(2) : null,
    startPos: gridNames.indexOf(a.name) + 1,
    delta: (gridNames.indexOf(a.name) + 1) - (i + 1)
  }));
