    trackLength: Math.round(L), laps, aiCount: r.ai.length,
    grid: gridInfo, finalOrder,
    winnerChanges: new Set(history.map((h) => h.order[0])).size,
    persistentSwaps, commits: passes.length, completedPasses: passes.filter((p) => p.success).length,
    passSample: passes.slice(0, 12),
    minGapSeen: isFinite(minGapSeen) ? +minGapSeen.toFixed(2) : null,
    overlapFrames,
    packedShare: +(worstFrames / Math.max(1, history.length)).toFixed(2),
    spreadSamples: history.filter((_, i) => i % 8 === 0).map((h) => [h.t, h.spread])
  };
